-- Seed SQLD SQL Lab interpretation drills.
-- Generated from src/data/questions/sqld/sql-interpretation-drills.json.
-- These are QuestDP original examples reconstructed from the SQLD scope; no source text is copied.

insert into public.questions (
  id, subject, chapter, chapter_title, topic, canonical_topic, subtopic,
  pass_number, difficulty, stem, choices, answer_index, explanation,
  lifecycle, is_playable, source_path, updated_at
) values
  ('sqld-sql-lab-001', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'SQL 명령군', 1, 1, '다음 명령어 묶음 중 역할 분류가 가장 자연스러운 것은?', '["CREATE, ALTER, DROP은 테이블 구조를 다루므로 DDL이다.","COMMIT, ROLLBACK은 권한을 다루므로 DCL이다.","GRANT, REVOKE는 트랜잭션 저장 여부를 다루므로 TCL이다.","INSERT, UPDATE, DELETE는 테이블 구조를 바꾸므로 DDL이다."]'::jsonb, 0, '"DDL은 객체 구조 정의·변경·삭제 계열입니다. COMMIT/ROLLBACK은 TCL, GRANT/REVOKE는 DCL, INSERT/UPDATE/DELETE는 DML입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-002', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'SELECT 논리 실행 순서', 1, 2, '다음 SQL이 실패하는 가장 직접적인 이유는?', '["WHERE가 SELECT보다 먼저 실행되어 YEAR_SAL 별칭을 알 수 없기 때문이다.","SAL * 12처럼 산술식을 SELECT에 쓸 수 없기 때문이다.","WHERE 절에서는 숫자 비교 연산자를 사용할 수 없기 때문이다.","EMP_ID를 함께 SELECT하면 반드시 GROUP BY가 필요하기 때문이다."]'::jsonb, 0, '"논리 처리 순서는 FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY입니다. SELECT에서 만든 별칭은 ORDER BY에서는 쓸 수 있지만 WHERE에서는 사용할 수 없습니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-003', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '관계대수', 1, 1, '관계대수 기호와 SQL 절의 연결로 가장 적절한 것은?', '["σ는 조건에 맞는 행을 고르는 연산이므로 WHERE와 가깝다.","π는 두 릴레이션의 교집합을 구하므로 INTERSECT와 같다.","×는 중복을 제거하는 연산이므로 DISTINCT와 같다.","∩는 모든 가능한 행 조합을 만들므로 CROSS JOIN과 같다."]'::jsonb, 0, '"σ(Selection)는 조건을 만족하는 행 선택, π(Projection)는 열 선택입니다. ×는 Cartesian product, ∩는 교집합입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-004', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'DISTINCT와 NULL', 1, 2, '다음 SQL의 결과로 가장 적절한 것은?', '["1행","2행","3행","4행"]'::jsonb, 1, '"DISTINCT는 선택한 컬럼 조합 전체가 같은 행을 하나로 줄입니다. 이 예시에서는 (1, APP), (2, NULL) 두 조합만 남습니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-005', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '문자 함수', 1, 2, 'Oracle 기준 다음 결과로 옳은 것은?', '["A=QUE, B=DP","A=UES, B=DP","A=UES, B=TP","A=EST, B=QP"]'::jsonb, 1, '"Oracle의 SUBSTR은 시작 위치가 1부터 시작합니다. 음수 시작 위치는 문자열 끝에서 거꾸로 세므로 -2는 뒤에서 두 번째 문자부터입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-006', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '숫자 함수', 1, 2, 'Oracle 기준 다음 식의 결과로 옳은 것은?', '["A=140, B=150","A=150, B=140","A=149, B=148","A=148.6, B=148"]'::jsonb, 1, '"ROUND(n, -1)은 10의 자리에서 반올림하고, TRUNC(n, -1)은 10의 자리 아래를 버립니다. 따라서 150과 140입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-007', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '집계 함수와 NULL', 1, 3, '다음 SQL 결과로 옳은 것은?', '["C1=3, C2=2, S=30","C1=2, C2=2, S=30","C1=3, C2=3, S=NULL","C1=3, C2=2, S=NULL"]'::jsonb, 0, '"COUNT(*)는 NULL 포함 전체 행 수를 세고, COUNT(컬럼)과 SUM/AVG/MIN/MAX는 NULL을 제외하고 계산합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-008', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'NULL 비교', 1, 2, '직업이 입력되지 않은 회원만 조회하려면 어떤 조건이 가장 적절한가?', '["JOB = NULL","JOB != NULL","JOB IS NULL","JOB IN NULL"]'::jsonb, 2, '"NULL은 일반 비교 연산자 =, !=로 비교하지 않습니다. NULL인 행은 IS NULL, NULL이 아닌 행은 IS NOT NULL을 사용합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-009', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'NULL 처리 함수', 1, 3, '다음 결과로 옳은 것은?', '["X=A, Y=NULL, Z=100","X=NULL, Y=100, Z=NULL","X=B, Y=NULL, Z=90","X=A, Y=100, Z=100"]'::jsonb, 0, '"COALESCE는 첫 NOT NULL인 A를 반환합니다. NULLIF(100,100)은 NULL, NULLIF(100,90)은 첫 번째 값 100을 반환합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-010', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'CASE와 NULL', 1, 3, 'COL 값이 NULL일 때 다음 Simple CASE의 결과는?', '["없음","기타","NULL","오류"]'::jsonb, 1, '"Simple CASE의 WHEN NULL은 NULL 비교 함정 때문에 원하는 대로 동작하지 않습니다. NULL 분기는 CASE WHEN COL IS NULL THEN ... 형태가 안전합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-011', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'LIKE와 ESCAPE', 1, 3, '상품명이 문자 그대로 ''_SALE''로 끝나는 행만 찾고 싶다. 가장 적절한 조건은?', '["LIKE ''%_SALE''","LIKE ''%/_SALE'' ESCAPE ''/''","LIKE ''_SALE%''","LIKE ''%-SALE'' ESCAPE ''_''"]'::jsonb, 1, '"_는 한 글자 와일드카드이므로 문자 자체의 밑줄을 찾으려면 ESCAPE를 써야 합니다. 여기서는 /_가 밑줄 문자 자체를 뜻합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-012', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '연산자 우선순위', 1, 3, '다음 조건을 만족하는 행 수는?', '["1행","2행","3행","0행"]'::jsonb, 2, '"괄호가 없으면 NOT, AND, OR 순으로 처리됩니다. 이 문제는 A=''Y''인 두 행과 B=''Y''이면서 ID=2인 한 행이 모두 통과합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-013', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'GROUP BY와 HAVING', 1, 3, '부서별 급여 합계가 1000 이상인 부서만 조회하려 한다. 빈칸에 들어갈 절로 가장 적절한 것은?', '["WHERE SUM(SAL) >= 1000","HAVING SUM(SAL) >= 1000","ORDER BY SUM(SAL) >= 1000","GROUP BY SUM(SAL) >= 1000"]'::jsonb, 1, '"WHERE는 행 단위 필터이고 집계 결과가 아직 없습니다. GROUP BY 이후의 집계값 조건은 HAVING 절을 사용합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-014', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'ORDER BY와 NULL', 1, 2, '오름차순 정렬 시 NULL 기본 위치에 대한 설명으로 가장 적절한 것은?', '["Oracle은 ASC에서 NULL을 뒤쪽에, SQL Server는 앞쪽에 둔다.","Oracle과 SQL Server 모두 NULL을 항상 맨 앞에 둔다.","Oracle과 SQL Server 모두 NULL을 항상 맨 뒤에 둔다.","NULL은 정렬 대상이 아니므로 ORDER BY를 쓰면 오류가 난다."]'::jsonb, 0, '"SQLD에서 자주 묻는 DBMS 차이입니다. Oracle은 ASC 기준 NULL이 뒤쪽, SQL Server는 ASC 기준 NULL이 앞쪽에 오는 것으로 정리합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-015', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'INNER JOIN 중복 매칭', 1, 3, '다음 INNER JOIN 결과 행 수는?', '["1행","2행","4행","6행"]'::jsonb, 2, '"JOIN은 같은 키가 여러 행이면 모든 조합을 만듭니다. A에 X가 2개, B에 X가 2개라서 결과는 4행입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-016', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'OUTER JOIN', 1, 2, '다음 LEFT OUTER JOIN 결과에 반드시 포함되는 행은?', '["민수, SQL","지아, NULL","민수, NULL","지아 행은 결과에서 제거된다."]'::jsonb, 1, '"LEFT OUTER JOIN은 왼쪽 테이블의 모든 행을 보존합니다. 오른쪽 테이블에 매칭이 없으면 오른쪽 컬럼만 NULL이 됩니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-017', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'NOT IN과 NULL', 1, 4, '계약이 없는 회원을 찾으려 한다. CONTRACT.MEMBER_ID에 NULL이 섞일 수 있을 때 가장 안전한 방식은?', '["WHERE M.ID NOT IN (SELECT MEMBER_ID FROM CONTRACT)","WHERE NOT EXISTS (SELECT 1 FROM CONTRACT C WHERE C.MEMBER_ID = M.ID)","WHERE M.ID <> (SELECT MEMBER_ID FROM CONTRACT)","WHERE EXISTS (SELECT 1 FROM CONTRACT C WHERE C.MEMBER_ID IS NULL)"]'::jsonb, 1, '"NOT IN은 서브쿼리 결과에 NULL이 섞이면 의도와 다르게 어떤 행도 확정적으로 통과하지 못할 수 있습니다. NOT EXISTS는 해당 회원의 매칭 존재 여부를 직접 확인하므로 안전합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-018', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', '집합 연산자', 1, 2, '집합 연산자에 대한 설명으로 옳은 것은?', '["UNION은 중복 행을 제거하고, UNION ALL은 중복을 유지한다.","INTERSECT는 첫 번째 결과에서 두 번째 결과를 빼는 차집합이다.","MINUS는 두 SELECT 결과를 모두 중복 포함해 이어 붙인다.","집합 연산자는 컬럼 개수와 데이터 타입이 달라도 자동 보정된다."]'::jsonb, 0, '"UNION은 중복을 제거하고 UNION ALL은 중복을 유지합니다. INTERSECT는 교집합, MINUS/EXCEPT는 차집합이며 컬럼 구조가 맞아야 합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-019', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'ROLLUP과 CUBE', 1, 3, 'ROLLUP(REGION, ITEM)의 그룹 생성 순서로 가장 적절한 것은?', '["(REGION, ITEM) → (REGION) → 전체","(REGION, ITEM) → (ITEM) → 전체","(REGION) → (ITEM) → (REGION, ITEM) → 전체","(REGION, ITEM) → (REGION) → (ITEM) → 전체"]'::jsonb, 0, '"ROLLUP은 컬럼 순서에 따라 오른쪽부터 하나씩 제거하며 소계와 총계를 만듭니다. CUBE는 가능한 모든 조합을 생성합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-020', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', '윈도우 순위 함수', 1, 3, '점수 내림차순이 100, 100, 90, 80일 때 RANK와 DENSE_RANK 결과로 옳은 것은?', '["RANK: 1,1,3,4 / DENSE_RANK: 1,1,2,3","RANK: 1,2,3,4 / DENSE_RANK: 1,1,3,4","RANK: 1,1,2,3 / DENSE_RANK: 1,1,3,4","RANK: 1,2,2,3 / DENSE_RANK: 1,2,3,4"]'::jsonb, 0, '"RANK는 동점 뒤 순위를 건너뜁니다. DENSE_RANK는 동점 뒤에도 순위를 건너뛰지 않습니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-021', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', '윈도우 함수와 GROUP BY', 1, 3, '윈도우 함수와 GROUP BY의 차이로 가장 적절한 것은?', '["윈도우 함수는 행 수를 유지한 채 계산값을 붙일 수 있다.","윈도우 함수는 반드시 결과 행 수를 그룹 수로 줄인다.","GROUP BY는 OVER 절이 있어야만 사용할 수 있다.","GROUP BY와 윈도우 함수는 출력 행 수가 항상 같다."]'::jsonb, 0, '"GROUP BY는 여러 행을 그룹별 한 행으로 줄이는 반면, 윈도우 함수는 기존 행을 유지하면서 각 행에 계산 결과를 붙일 수 있습니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-022', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'ROWS와 RANGE', 1, 4, 'ORDER BY 값이 10, 10, 20일 때 누적합에서 ROWS와 RANGE의 차이를 가장 잘 설명한 것은?', '["ROWS는 실제 행 단위로 누적하고, RANGE는 같은 정렬값을 같은 범위로 묶을 수 있다.","ROWS는 동점 행을 항상 제외하고, RANGE는 NULL 행만 계산한다.","ROWS와 RANGE는 어떤 DBMS에서도 완전히 같은 결과만 만든다.","RANGE는 GROUP BY가 있을 때만 사용할 수 있고 윈도우 함수와는 무관하다."]'::jsonb, 0, '"ROWS는 물리적인 행 수 기준이고 RANGE는 정렬 값의 범위 기준입니다. 같은 ORDER BY 값이 있는 경우 누적 결과가 달라질 수 있습니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-023', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'LAST_VALUE 프레임', 1, 4, 'LAST_VALUE를 파티션의 진짜 마지막 값으로 쓰려면 주의해야 할 점은?', '["프레임 끝을 UNBOUNDED FOLLOWING까지 넓혀야 의도한 마지막 행을 볼 수 있다.","LAST_VALUE는 ORDER BY 없이만 사용할 수 있다.","LAST_VALUE는 GROUP BY와 함께 쓰면 항상 전체 마지막 값을 반환한다.","LAST_VALUE는 NULL이 하나라도 있으면 문법 오류가 난다."]'::jsonb, 0, '"기본 프레임은 현재 행까지로 제한되는 경우가 많아 LAST_VALUE가 현재 행 값을 반환할 수 있습니다. 전체 파티션의 마지막 값을 보려면 프레임을 끝까지 지정해야 합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-024', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'TOP N과 ROWNUM', 1, 3, 'Oracle에서 매출 상위 3건을 안정적으로 조회하는 방식으로 가장 적절한 것은?', '["SELECT * FROM (SELECT * FROM SALE ORDER BY AMT DESC) WHERE ROWNUM <= 3","SELECT * FROM SALE WHERE ROWNUM <= 3 ORDER BY AMT DESC","SELECT * FROM SALE WHERE ROWNUM = 3 ORDER BY AMT DESC","SELECT * FROM SALE WHERE ROWNUM > 3 ORDER BY AMT DESC"]'::jsonb, 0, '"Oracle의 ROWNUM은 정렬 전에 붙을 수 있으므로 먼저 인라인 뷰에서 ORDER BY를 수행한 뒤 바깥에서 ROWNUM <= N을 거는 방식이 안전합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-025', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', '계층형 질의', 1, 3, 'Oracle 계층형 질의에서 루트 행을 지정하는 절은?', '["START WITH","CONNECT BY","ORDER SIBLINGS BY","SYS_CONNECT_BY_PATH"]'::jsonb, 0, '"START WITH는 계층 탐색을 시작할 루트 조건을 지정합니다. CONNECT BY는 부모-자식 연결 규칙, ORDER SIBLINGS BY는 같은 레벨 정렬입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-026', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'PIVOT', 1, 3, 'PIVOT에 대한 설명으로 가장 적절한 것은?', '["행 값을 열 방향으로 펼치며, 여러 행을 한 칸으로 모으기 위해 집계 함수가 필요하다.","열을 행으로 바꾸는 기능이므로 UNPIVOT과 완전히 같은 문법이다.","PIVOT은 WHERE 절에서만 사용할 수 있고 FROM 절에서는 사용할 수 없다.","PIVOT은 NULL 비교 전용 함수라서 집계와는 관계가 없다."]'::jsonb, 0, '"PIVOT은 LONG 형태의 행 값을 WIDE 형태의 열로 재구성합니다. 여러 행이 같은 교차점에 모일 수 있으므로 MAX, SUM 같은 집계 함수가 필요합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-027', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', '정규 표현식', 1, 3, 'Oracle 기준 휴대전화 번호가 010으로 시작하는지 검사하는 조건으로 가장 적절한 것은?', '["REGEXP_LIKE(PHONE, ''^010'')","REGEXP_LIKE(PHONE, ''010$'')","REGEXP_LIKE(PHONE, ''[^010]'')","REGEXP_LIKE(PHONE, ''010?'')"]'::jsonb, 0, '"^는 문자열의 시작을 뜻합니다. 따라서 ''^010''은 010으로 시작하는 문자열을 검사합니다. ''$''는 끝, ''[^...]''는 부정 문자 집합입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-028', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'INSERT', 1, 2, '다음 INSERT 실행 후 AMT 컬럼 값으로 가장 적절한 것은?', '["0","1","NULL","문자열 빈 값"]'::jsonb, 2, '"INSERT에서 컬럼 목록을 명시하면 그 컬럼에만 값이 들어갑니다. 생략된 컬럼은 기본값이 있으면 기본값, 없고 NULL 허용이면 NULL입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-029', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'UPDATE와 DELETE', 1, 2, 'UPDATE나 DELETE에서 WHERE 절을 생략했을 때의 설명으로 옳은 것은?', '["조건이 없으므로 대상 테이블의 모든 행에 적용될 수 있다.","WHERE가 없으면 SQL 표준상 항상 문법 오류가 난다.","첫 번째 행에만 적용되고 나머지 행은 유지된다.","PK가 있는 행만 자동으로 제외된다."]'::jsonb, 0, '"UPDATE와 DELETE에서 WHERE 절은 대상을 제한하는 역할입니다. WHERE를 생략하면 모든 행이 대상이 될 수 있어 매우 위험합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-030', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'MERGE', 1, 3, 'MERGE 문에서 ON 조건을 만족하는 기존 행에 주로 수행되는 절은?', '["WHEN MATCHED THEN UPDATE","WHEN NOT MATCHED THEN INSERT","WHEN MATCHED THEN CREATE","WHEN NOT MATCHED THEN COMMIT"]'::jsonb, 0, '"MERGE는 원본 데이터와 대상 테이블을 비교해 있으면 UPDATE, 없으면 INSERT하는 형태가 일반적입니다. ON 조건을 만족하면 MATCHED 분기로 갑니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-031', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'SAVEPOINT', 1, 3, '다음 실행 후 T에 남는 최종 행은?', '["1만 남는다","1과 2가 남는다","1, 2, 3이 모두 남는다","모든 행이 사라진다"]'::jsonb, 1, '"ROLLBACK TO S2는 S2 이후 작업만 되돌립니다. S2 이전에 수행된 1, 2 삽입은 유지됩니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-032', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'TRUNCATE와 DROP', 1, 2, 'DELETE, TRUNCATE, DROP 비교로 옳은 것은?', '["DELETE는 행 삭제, TRUNCATE는 데이터 비우기, DROP은 객체 삭제에 가깝다.","TRUNCATE는 WHERE 절로 일부 행만 선택해 삭제하는 DML이다.","DROP은 데이터만 지우고 테이블 구조는 항상 유지한다.","DELETE는 DDL이므로 일반적으로 ROLLBACK 대상이 아니다."]'::jsonb, 0, '"DELETE는 DML로 행을 삭제합니다. TRUNCATE는 DDL 성격으로 테이블 구조는 남기고 데이터를 비우며, DROP은 테이블 객체 자체를 삭제합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-033', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', '제약조건', 1, 2, '제약조건 설명으로 옳지 않은 것은?', '["PRIMARY KEY는 중복과 NULL을 허용하지 않는다.","FOREIGN KEY는 참조 무결성과 관련된다.","UNIQUE는 일반적으로 중복 값을 제한한다.","CHECK는 다른 테이블의 행 존재 여부를 항상 직접 검사하는 제약조건이다."]'::jsonb, 3, '"CHECK는 한 행의 컬럼 값이 조건을 만족하는지 제한하는 데 사용합니다. 다른 테이블 참조 관계는 FOREIGN KEY의 영역입니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-034', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', '문자 자료형', 1, 2, 'CHAR와 VARCHAR 비교로 가장 적절한 것은?', '["CHAR는 고정 길이, VARCHAR는 가변 길이 문자열 저장에 적합하다.","CHAR는 숫자 전용이고 VARCHAR는 날짜 전용이다.","VARCHAR는 항상 고정 길이로 공백을 채운다.","CHAR와 VARCHAR는 SQLD에서 완전히 같은 자료형으로 본다."]'::jsonb, 0, '"CHAR(n)은 고정 길이 문자열, VARCHAR(n)은 최대 길이 안에서 실제 값 길이에 맞춰 저장하는 가변 길이 문자열로 이해하면 됩니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-035', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', '권한 부여 옵션', 1, 3, 'WITH GRANT OPTION에 대한 설명으로 가장 적절한 것은?', '["객체 권한을 받은 사용자가 그 권한을 다른 사용자에게 다시 부여할 수 있게 한다.","시스템 권한을 받은 사용자가 테이블 구조를 자동으로 백업하게 한다.","권한 회수 시 이미 전달된 권한이 절대 영향을 받지 않게 한다.","COMMIT 없이도 DML을 영구 저장하게 만드는 TCL 옵션이다."]'::jsonb, 0, '"WITH GRANT OPTION은 객체 권한을 다른 사용자에게 다시 부여할 수 있게 하는 옵션입니다. 시스템 권한 재부여는 WITH ADMIN OPTION과 구분합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now()),
  ('sqld-sql-lab-036', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', 'M:N 관계와 교차 엔터티', 1, 2, '학생과 과목이 서로 M:N 관계일 때 관계형 데이터베이스 모델에서 가장 자연스러운 설계는?', '["학생과 과목 사이에 수강 같은 교차 엔터티를 두어 두 개의 1:M 관계로 푼다.","학생 테이블의 한 컬럼에 모든 과목명을 쉼표로 이어 저장한다.","과목 테이블을 없애고 학생 이름을 과목명으로 사용한다.","M:N 관계는 관계형 데이터베이스에서 아무 처리 없이 그대로 PK가 된다."]'::jsonb, 0, '"관계형 DB에서 M:N 관계는 직접 표현하기 어렵습니다. 보통 수강, 주문상세 같은 교차 엔터티를 두어 두 개의 1:M 관계로 분해합니다."'::jsonb, 'guidebook-verified', true, 'src/data/questions/sqld/sql-interpretation-drills.json', now())
